import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { DomSanitizer } from '@angular/platform-browser';
import { Router } from '@angular/router';
import { AlertController, LoadingController, ToastController } from '@ionic/angular';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { Urls } from 'src/app/core/common/Urls';
import { CourseService } from 'src/app/data/service/course/course.service';
import { SliderService } from 'src/app/data/service/site/Slider.service';
import { VehicleProfile, VehicleProfileStore } from '../vehicle-profile/vehicle-profile.store';

interface VoltageTableRow {
  voltage: number;
  dwellMs: number;
  deadTimeMs: number;
}

@Component({
  selector: 'app-electrical-calibration',
  templateUrl: './electrical-calibration.component.html',
  styleUrls: ['./electrical-calibration.component.scss'],
})
export class ElectricalCalibrationComponent implements OnInit {

  isShow = false;
  isCheck = true;
  profiles: VehicleProfile[] = [];
  selectedProfileId = '';
  profileNotice = '';
  private loadedProfileUpdatedAt = '';
  form: FormGroup;
  voltageRows: VoltageTableRow[] = [];
  injectorFlowCorrectionPct = 100;

  constructor(private fb: FormBuilder,
    private router: Router,
    public alertController: AlertController,
    private sanitizer: DomSanitizer,
    public loadingController: LoadingController,
    public toastController: ToastController,
    private courseService: CourseService,
    private siteService: SliderService) {

    this.isShow = false;
    this.check();
  }

  ionViewWillEnter(): void {
    this.profiles = VehicleProfileStore.list();
    const active = VehicleProfileStore.active();
    if (active && this.form && (active.id !== this.selectedProfileId ||
      active.updatedAt !== this.loadedProfileUpdatedAt)) {
      this.applyProfile(active.id);
    }
  }

  applyProfile(id: string): void {
    const profile = this.profiles.find(item => item.id === id);
    if (!profile || !this.form) { return; }
    const values = VehicleProfileStore.toolValues(profile, 'electrical-calibration');
    let applied = 0;
    Object.keys(values).forEach(key => {
      const control = this.form.get(key);
      if (!control) { return; }
      const previous = control.value;
      control.setValue(values[key], { emitEvent: false });
      if (control.invalid) { control.setValue(previous, { emitEvent: false }); }
      else { applied++; }
    });

    this.form.updateValueAndValidity();
    this.profileNotice = `${applied} مقدار از پروفایل اعمال شد؛ سایر ورودی‌ها پیش‌فرض ابزارند.`;
    this.selectedProfileId = id;
    this.loadedProfileUpdatedAt = profile.updatedAt;
    try { VehicleProfileStore.select(id); } catch { /* Local storage may be disabled. */ }
    this.calculate();
  }

  async check() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetTunerPlusById(39).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      if (ress.data.find(n => n == courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;
                              this.isShow = true;
                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
              this.isShow = true;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  ngOnInit(): void {
    this.form = this.fb.group({
      nominalVoltage: [14, [Validators.required, Validators.min(10), Validators.max(16)]],
      dwellAtNominalVoltageMs: [2.5, [Validators.required, Validators.min(0.2), Validators.max(10)]],
      minimumDwellMs: [1.5, [Validators.required, Validators.min(0.1), Validators.max(10)]],
      maximumDwellMs: [5, [Validators.required, Validators.min(0.2), Validators.max(15)]],
      injectorDeadTimeAtNominalVoltageMs: [0.85, [Validators.required, Validators.min(0), Validators.max(5)]],
      injectorVoltageSensitivityMsPerV: [0.17, [Validators.required, Validators.min(0), Validators.max(1)]],
      baseFuelPressureBar: [3, [Validators.required, Validators.min(0.1), Validators.max(10)]],
      targetFuelPressureBar: [3, [Validators.required, Validators.min(0.1), Validators.max(10)]],
    });
    this.profiles = VehicleProfileStore.list();
    const active = VehicleProfileStore.active();
    if (active) { this.applyProfile(active.id); }

    this.form.valueChanges.subscribe(() => this.calculate());
    this.calculate();
  }

  calculate(): void {
    if (this.form.invalid) {
      this.voltageRows = [];
      return;
    }

    const value = this.form.getRawValue();
    const nominalVoltage = Number(value.nominalVoltage);
    const dwellAtNominal = Number(value.dwellAtNominalVoltageMs);
    const minimumDwell = Number(value.minimumDwellMs);
    const maximumDwell = Number(value.maximumDwellMs);
    const deadTimeAtNominal = Number(value.injectorDeadTimeAtNominalVoltageMs);
    const voltageSensitivity = Number(value.injectorVoltageSensitivityMsPerV);

    if (maximumDwell < minimumDwell) {
      this.voltageRows = [];
      return;
    }

    this.voltageRows = [];
    for (let voltage = 8; voltage <= 16; voltage += 0.5) {
      // A first-pass dwell curve scales inverse to available voltage and is
      // constrained by the coil manufacturer's safe min/max dwell values.
      const dwellMs = this.clamp(dwellAtNominal * nominalVoltage / voltage, minimumDwell, maximumDwell);
      // Injector latency is approximately linear across the usable ECU voltage
      // range. The sensitivity is user-supplied because it is injector-specific.
      const deadTimeMs = Math.max(0, deadTimeAtNominal + (nominalVoltage - voltage) * voltageSensitivity);
      this.voltageRows.push({
        voltage: this.round(voltage, 1),
        dwellMs: this.round(dwellMs, 2),
        deadTimeMs: this.round(deadTimeMs, 2),
      });
    }

    this.injectorFlowCorrectionPct = this.round(
      Math.sqrt(Number(value.targetFuelPressureBar) / Number(value.baseFuelPressureBar)) * 100,
      1,
    );
  }

  reset(): void {
    this.form.reset({
      nominalVoltage: 14,
      dwellAtNominalVoltageMs: 2.5,
      minimumDwellMs: 1.5,
      maximumDwellMs: 5,
      injectorDeadTimeAtNominalVoltageMs: 0.85,
      injectorVoltageSensitivityMsPerV: 0.17,
      baseFuelPressureBar: 3,
      targetFuelPressureBar: 3,
    });
  }

  get validDwellRange(): boolean {
    return this.form && Number(this.form.value.maximumDwellMs) >= Number(this.form.value.minimumDwellMs);
  }

  async onInfo(type: string): Promise<void> {
    const messages: Record<string, string> = {
      voltage: 'ولتاژی که dwell و dead-time مرجع در آن اندازه‌گیری یا از دیتاشیت اعلام شده است؛ معمولاً 13.5 تا 14.0 ولت.',
      dwell: 'زمان شارژ کویل در ولتاژ مرجع. فقط مقدار تأییدشده برای همان کویل و ECU را وارد کنید.',
      dwellMin: 'کمترین زمان شارژ مجاز کویل برای جلوگیری از افت انرژی جرقه در ولتاژ بالا.',
      dwellMax: 'بیشترین dwell ایمن کویل؛ افزایش بیش از آن می‌تواند کویل یا درایور ECU را داغ کند.',
      deadTime: 'تاخیر بازشدن انژکتور در ولتاژ مرجع؛ این زمان به pulse width افزوده می‌شود.',
      sensitivity: 'تغییر تقریبی dead-time به ازای هر یک ولت تغییر ولتاژ باتری. مقدار دقیق، مختص مدل انژکتور است.',
      pressure: 'فشار مرجع یا هدف سوخت. تغییر فشار دبی انژکتور را با ریشه دوم نسبت فشار تغییر می‌دهد.',
    };
    await this.presentInfo(messages[type] || 'توضیحی برای این پارامتر موجود نیست.');
  }

  private async presentInfo(message: string): Promise<void> {
    const alert = await this.alertController.create({ cssClass: 'main-alert', header: 'توضیحات', message, buttons: ['بستن'] });
    await alert.present();
  }

  private clamp(value: number, min: number, max: number): number {
    return Math.min(max, Math.max(min, value));
  }

  private round(value: number, decimals: number): number {
    const factor = Math.pow(10, decimals);
    return Math.round((value + Number.EPSILON) * factor) / factor;
  }
}
